INSERT INTO ui.ui_surface_value (surface_name, name, label, description, value_type, always_available, typical_char_count, sort_order, auto_context, group_key) VALUES
('matrx-public/p', 'app_id', 'App ID', 'UUID of the published `app.definition` row being run (`app.id`). Always available — the page 404s before rendering if the slug/id does not resolve to a published, public app.', 'string', true, 36, 100, true, 'app_identity'),
('matrx-public/p', 'app_slug', 'App slug', 'The app''s public URL slug (`app.slug`), as used in `/p/[slug]`. Always available.', 'string', true, 40, 110, true, 'app_identity'),
('matrx-public/p', 'app_name', 'App name', 'Display name of the app (`app.name`). Always available.', 'string', true, 60, 120, true, 'app_identity'),
('matrx-public/p', 'agent_id', 'Bound agent ID', 'UUID of the `agent.definition` the app is bound to (`app.agent_id`) — the agent `launchAgentExecution` runs on submit. Always available.', 'string', true, 36, 130, false, 'app_identity'),
('matrx-public/p', 'agent_version_id', 'Pinned agent version ID', 'UUID of the pinned `agx_version` row when the app is NOT configured to use_latest (`app.agent_version_id`). Empty when the app tracks the agent''s latest published version.', 'string', false, 36, 140, false, 'app_identity'),
('matrx-public/p', 'shell_kind', 'Shell kind', 'Which top-level UI shell renders the app (`app.shell_kind`) — e.g. "chat", "form_to_result", "widget", "fully_custom". Always available. `?embed=widget` forces "widget" regardless of the row''s configured kind.', 'string', true, 16, 150, false, 'app_identity'),
('matrx-public/p', 'is_authenticated', 'Visitor is signed in', 'True when the visitor has a real Supabase session; false for an anonymous guest identified only by fingerprint. Always available.', 'boolean', true, 5, 200, true, 'visitor'),
('matrx-public/p', 'guest_fingerprint_id', 'Guest fingerprint ID', 'Browser fingerprint identifying an anonymous visitor across runs (`X-Fingerprint-ID`), used in place of a user id for guest rate limiting. Empty once the visitor is authenticated or before the fingerprint has resolved.', 'string', false, 40, 210, false, 'visitor'),
('matrx-public/p', 'guest_runs_remaining', 'Guest runs remaining', 'Free executions left for this anonymous guest before signup is required (from `useGuestLimit`). Meaningless once `is_authenticated` is true.', 'number', false, 2, 220, false, 'visitor'),
('matrx-public/p', 'user_input', 'User message', 'Free-text message the visitor typed for this run, passed as `runtime.userInput` to the agent. Empty for apps whose custom UI collects only form variables and no chat-style message.', 'string', false, 300, 300, true, 'run_input'),
('matrx-public/p', 'form_variable_values', 'Form variable values', 'The visitor''s submitted form values, validated and coerced against `app.variable_schema` (string/number/boolean per field, required fields defaulted or flagged). Object keyed by variable name. Empty object for apps with no declared variables.', 'object', false, 400, 310, true, 'run_input'),
('matrx-public/p', 'conversation_id', 'Conversation ID', 'UUID of the `cx_conversation` row created for this run, captured synchronously via `onConversationCreated` right after the launcher creates it. Empty until the visitor''s first submit of this page view.', 'string', false, 36, 400, true, 'run_state'),
('matrx-public/p', 'run_status', 'Run status', 'Status of the active/most-recent execution''s request: "streaming", "complete", "error", or empty before any run has started this page view.', 'string', false, 12, 410, false, 'run_state'),
('matrx-public/p', 'response_text', 'Response text', 'Accumulated streamed text of the current/most recent run, read live from Redux (`selectAccumulatedText`). Empty before the first run completes any output.', 'string', false, 2000, 420, false, 'run_state'),
('matrx-public/p', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-public/p', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-public/p', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-public/p', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-public/p', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline')
